// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract RecordingCounterparty {
    mapping(address => uint256) public calls;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        from;
        amount;
        calls[to] += 1;
        return true;
    }
}

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address recipient, uint256 amount) public {
        vm.assume(from != address(0));
        vm.assume(recipient != address(0));

        RecordingCounterparty recorder = new RecordingCounterparty();

        address[] memory tos = new address[](1);
        tos[0] = recipient;

        bool ok = c.transfer(from, address(recorder), tos, amount);
        assertTrue(ok);

        assertTrue(recorder.calls(recipient) >= 1);
    }
}
